const obj = { imie: "Ola", wiek: 22, miasto: "Poznan" };
const mapa = new Map(Object.entries(obj));
console.log(mapa); // Map(3) {"imie" => "Ola", "wiek" => 22, "miasto" => "Poznan"}

const obj = { imie: "Ola", wiek: 22, miasto: "Poznan" };
const mapa = new Map(Object.entries(obj));
const backToObj = Object.fromEntries(mapa);
console.log(backToObj); // { imie: "Ola", wiek: 22, miasto: "Poznan" }

const zbior = new Set(["kot", "pies", "chomik"]);
const tablica = Array.from(zbior);
console.log(tablica); // ["kot", "pies", "chomik"]

const liczby = [1, 2, 3, 2, 1];
const unikalne = Array.from(new Set(liczby));
console.log(unikalne); // [1, 2, 3]
// Ten "roundtrip" (tablica -> Set -> tablica) sluzy do DEDUPLIKACJI -
// konwersja do Set automatycznie odrzuca duplikaty (bo Set przechowuje
// wylacznie unikalne wartosci), a konwersja z powrotem do tablicy daje
// wygodny, znany format do dalszej pracy (np. .map(), .filter()).

const mapa = new Map([[42, "wartosc"]]);
const obj = Object.fromEntries(mapa);
console.log(typeof Object.keys(obj)[0]); // "string" - liczba 42 stala sie stringiem "42"

const konfiguracjaMap = new Map([["timeout", 5000], ["retries", 3], ["debug", false]]);
const konfiguracjaObj = Object.fromEntries(konfiguracjaMap);
console.log(JSON.stringify(konfiguracjaObj));
// '{"timeout":5000,"retries":3,"debug":false}'

const slowa = ["kot", "pies", "kot", "rybka", "pies"];
const liczbaUnikalnych = Array.from(new Set(slowa)).length;
console.log(liczbaUnikalnych); // 3

const kluczObiekt = { id: 1 };
const mapa = new Map([[kluczObiekt, "dane dla obiektu"]]);

const obj = Object.fromEntries(mapa);
console.log(Object.keys(obj)); // ["[object Object]"] - klucz UTRACIL swoja tozsamosc!

// Konwersja Map -> Object jest bezpieczna tylko dla kluczy-stringow, bo
// obiekt WYMAGA kluczy string/symbol i AUTOMATYCZNIE konwertuje kazdy inny
// typ na string. Dla liczb konwersja jest wzglednie "bezpieczna" (42 staje
// sie "42", wciaz czytelne), ale dla obiektow konwersja jest DESTRUKCYJNA -
// kazdy obiekt-klucz staje sie tym samym, bezuzytecznym stringiem
// "[object Object]", co powoduje UTRATE informacji i mozliwe KOLIZJE, jesli
// Map mialaby wiecej niz jeden klucz-obiekt.

const obiekt = { a: 1, b: 2 };
const odwrocony = Object.fromEntries(Object.entries(obiekt).map(([k, v]) => [v, k]));

console.log(odwrocony); // -> { "1": "a", "2": "b" }

const obiekt = { a: 1, b: 5, c: 9 };
const wynik = Object.fromEntries(Object.entries(obiekt).filter(([k, v]) => v > 3));

console.log(wynik); // -> { b: 5, c: 9 }

const obiekt = { x: 1, y: 2, z: 3 };
const podwojony = Object.fromEntries(Object.entries(obiekt).map(([k, v]) => [k, v * 2]));

console.log(podwojony); // -> { x: 2, y: 4, z: 6 }

const mapa = new Map([["a", 1], ["b", 2]]);
const tekst = JSON.stringify([...mapa]);
console.log(tekst); // -> [["a",1],["b",2]]

const odtworzona = new Map(JSON.parse(tekst));
console.log(odtworzona.get("b")); // -> 2

const zbior = new Set([3, 1, 2]);
console.log(JSON.stringify(zbior));       // -> {}
const tekst = JSON.stringify([...zbior]);
console.log(tekst);                       // -> [3,1,2]

const odtworzony = new Set(JSON.parse(tekst));
console.log(odtworzony.size);             // -> 3

const mapa = new Map([[1, "liczba"], ["1", "napis"]]);
console.log(mapa.size); // -> 2

const obiekt = Object.fromEntries(mapa);
console.log(Object.keys(obiekt)); // -> ["1"]
console.log(obiekt);              // -> { "1": "napis" }
// Oba klucze zamienily sie w napis "1" - pozniejszy wpis nadpisal wczesniejszy.

const klucz = { id: 1 };
const mapa = new Map([[klucz, "x"]]);
const obiekt = Object.fromEntries(mapa);

console.log(Object.keys(obiekt)); // -> ["[object Object]"]
// Informacja o kluczu-obiekcie zostala utracona - dlatego konwersja jest bezpieczna tylko dla kluczy tekstowych.

const obiekt = { b: 1, 2: "x", a: 2, 1: "y" };

console.log(Object.keys(obiekt));                          // -> ["1", "2", "b", "a"]
console.log([...new Map(Object.entries(obiekt)).keys()]);  // -> ["1", "2", "b", "a"]
// Kolejnosc ustala juz sam obiekt - Map zachowuje ja w takiej postaci, a klucze pozostaja napisami.

const dane = [{ id: 2, nazwa: "b" }, { id: 1, nazwa: "a" }];
const poId = new Map(dane.map(o => [o.id, o]));

const posortowane = [...poId.values()].sort((x, y) => x.id - y.id);
console.log(posortowane.map(o => o.nazwa)); // -> ["a", "b"]

const pary = [["jablko", 3], ["gruszka", 5]];
const mapa = new Map(pary);
const obiekt = Object.fromEntries(mapa);

console.log(mapa.get("gruszka")); // -> 5
console.log(obiekt);              // -> { jablko: 3, gruszka: 5 }

const zbior = new Set(["kot", "pies", "ryba"]);
const dlugosci = new Map([...zbior].map(s => [s, s.length]));

console.log(dlugosci); // -> Map(3) { "kot" => 3, "pies" => 4, "ryba" => 4 }

const m = new Map([["a", 1], ["b", 2], ["c", 1]]);
const klucze = new Set(m.keys());
const wartosci = new Set(m.values());

console.log(klucze.size);   // -> 3
console.log(wartosci.size); // -> 2 (wartosc 1 powtarza sie)

const licznik = new Map();
for (const znak of "banan") {
  licznik.set(znak, (licznik.get(znak) || 0) + 1);
}

console.log(Object.fromEntries(licznik)); // -> { b: 1, a: 3, n: 2 }

const tablica = ["x", "y", "z"];
const mapa = new Map(tablica.entries());
const obiekt = Object.fromEntries(tablica.entries());

console.log(mapa);   // -> Map(3) { 0 => "x", 1 => "y", 2 => "z" }
console.log(obiekt); // -> { "0": "x", "1": "y", "2": "z" }

const oryginal = new Map([["a", { n: 1 }]]);

const gleboka = structuredClone(oryginal);
gleboka.get("a").n = 999;
console.log(oryginal.get("a").n); // -> 1 (niezalezna kopia)

const plytka = new Map(oryginal);
plytka.get("a").n = 999;
console.log(oryginal.get("a").n); // -> 999 (obiekt-wartosc wspoldzielony)

const dane = [[1, 2], [3], [1, 2]];
const unikalne = [...new Set(dane.map(t => JSON.stringify(t)))].map(t => JSON.parse(t));

console.log(unikalne); // -> [[1, 2], [3]]

const obiekt = { a: 1, b: 2, c: 1 };
const unikalne = [...new Set(Object.values(obiekt))];

console.log(unikalne);        // -> [1, 2]
console.log(unikalne.length); // -> 2

const obiekt = { a: 1, b: 2 };
const mapa = new Map([["b", 20], ["c", 3]]);
const polaczona = new Map([...Object.entries(obiekt), ...mapa]);

console.log(polaczona); // -> Map(3) { "a" => 1, "b" => 20, "c" => 3 }
// Wartosc z Mapy (20) nadpisala wartosc z obiektu (2).

const slowa = ["ala", "kot", "pies", "dom"];
const grupy = new Map();
for (const s of slowa) {
  if (!grupy.has(s.length)) grupy.set(s.length, []);
  grupy.get(s.length).push(s);
}

console.log(Object.fromEntries(grupy)); // -> { "3": ["ala", "kot", "dom"], "4": ["pies"] }

function takieSameZbiory(a, b) {
  const sa = new Set(a);
  const sb = new Set(b);
  return sa.size === sb.size && [...sa].every(x => sb.has(x));
}

console.log(takieSameZbiory([1, 2, 2], [2, 1])); // -> true
console.log(takieSameZbiory([1, 2], [1, 3]));    // -> false

const obiekt = { a: 1 };
const mapa = new Map([["a", 1]]);
const zbior = new Set([1, 2]);

console.log(new Map(Object.entries(obiekt))); // Object -> Map (klucze pozostaja napisami)
console.log(Object.fromEntries(mapa));        // Map -> Object (klucze zamieniane na napisy!)
console.log([...zbior]);                      // Set -> Array
console.log(new Set([1, 1, 2]));              // Array -> Set (usuwa duplikaty)
console.log([...mapa]);                       // Map -> Array par
console.log(new Map([["x", 1]]));             // Array par -> Map

